import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] grid = new int[n][n];
        int zeroRow = -1, zeroCol = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = sc.nextInt();
                if (grid[i][j] == 0) {
                    zeroRow = i;
                    zeroCol = j;
                }
            }
        }

        long target = 0;
        for (int i = 0; i < n; i++) {
            if (i != zeroRow) {
                long s = 0;
                for (int j = 0; j < n; j++) s += grid[i][j];
                target = s;
                break;
            }
        }

        long rowSum = 0;
        for (int j = 0; j < n; j++) rowSum += grid[zeroRow][j];
        long missing = target - rowSum;

        System.out.println(missing);
        System.out.println(zeroRow + 1);
        System.out.println(zeroCol + 1);
    }
}
